package com.retail.purchases;
import java.math.BigDecimal;
import java.util.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import com.retail.common.audit.AuditService;
@RestController @RequestMapping("/api/v1/purchase-orders")
public class PurchaseController {
 private final JdbcTemplate jdbc;private final AuditService audit;public PurchaseController(JdbcTemplate j,AuditService audit){jdbc=j;this.audit=audit;}
 public record OrderLine(@NotNull UUID productId,@Min(1) int quantity,@NotNull @DecimalMin("0") BigDecimal unitCost){}public record Order(@NotNull UUID supplierId,@NotBlank @Pattern(regexp="USD|KHR") String currency,@NotEmpty List<@Valid OrderLine> lines){}public record ReceiptLine(@NotNull UUID orderLineId,@Min(1) int quantity){}public record Receipt(@NotEmpty List<@Valid ReceiptLine> lines){}
 @PostMapping @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER','INVENTORY_STAFF')") public Map<String,Object> create(@Valid @RequestBody Order r,Authentication a){if(!a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_SUPER_ADMIN")||x.getAuthority().equals("ROLE_INVENTORY_STAFF")))throw new org.springframework.security.access.AccessDeniedException("Central purchasing is restricted to warehouse staff");UUID id=UUID.randomUUID();String no="PO-"+id.toString().substring(0,12).toUpperCase(Locale.ROOT);UUID warehouse=jdbc.queryForObject("select id from locations where type='CENTRAL_WAREHOUSE' and active=true limit 1",UUID.class);UUID actor=jdbc.queryForObject("select id from users where username=?",UUID.class,a.getName());jdbc.update("insert into purchase_orders(id,order_no,supplier_id,warehouse_location_id,status,currency_code,created_by) values (?,?,?,?,'ORDERED',?,?)",id,no,r.supplierId(),warehouse,r.currency(),actor);for(var l:r.lines()){String name=jdbc.queryForObject("select name from products where id=? and active=true",String.class,l.productId());jdbc.update("insert into purchase_order_lines(purchase_order_id,product_id,name_snapshot,ordered_quantity,unit_cost) values (?,?,?,?,?)",id,l.productId(),name,l.quantity(),l.unitCost());}audit.record(a.getName(),"PURCHASE_ORDER_CREATED","PURCHASE_ORDER",id,null);return Map.of("id",id,"orderNo",no,"status","ORDERED");}
 @GetMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','INVENTORY_STAFF')") public Map<String,Object> get(@PathVariable UUID id){return Map.of("order",jdbc.queryForMap("select * from purchase_orders where id=?",id),"lines",jdbc.queryForList("select * from purchase_order_lines where purchase_order_id=? order by id",id));} @PostMapping("/{id}/receipts") @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','INVENTORY_STAFF')") public Map<String,Object> receive(@PathVariable UUID id,@Valid @RequestBody Receipt req,@RequestHeader("Idempotency-Key") String key,Authentication a){var prior=jdbc.queryForList("select id,receipt_no from goods_receipts where idempotency_key=?",key);if(!prior.isEmpty())return prior.getFirst();var po=jdbc.queryForMap("select * from purchase_orders where id=? for update",id);if(Set.of("CANCELLED","RECEIVED").contains(po.get("status")))throw new IllegalStateException("Purchase order cannot receive goods");UUID actor=jdbc.queryForObject("select id from users where username=?",UUID.class,a.getName()),receipt=UUID.randomUUID();String no="GR-"+receipt.toString().substring(0,12).toUpperCase(Locale.ROOT);jdbc.update("insert into goods_receipts(id,receipt_no,purchase_order_id,status,idempotency_key,received_by) values (?,?,?,'CONFIRMED',?,?)",receipt,no,id,key,actor);UUID location=(UUID)po.get("warehouse_location_id");for(var line:req.lines()){var ol=jdbc.queryForMap("select * from purchase_order_lines where id=? and purchase_order_id=? for update",line.orderLineId(),id);int qty=line.quantity();if((Integer)ol.get("received_quantity")+qty>(Integer)ol.get("ordered_quantity"))throw new IllegalArgumentException("Receipt exceeds outstanding order quantity");jdbc.update("update purchase_order_lines set received_quantity=received_quantity+? where id=?",qty,line.orderLineId());UUID product=(UUID)ol.get("product_id");jdbc.update("insert into goods_receipt_lines(receipt_id,purchase_order_line_id,product_id,quantity,unit_cost) values (?,?,?,?,?)",receipt,line.orderLineId(),product,qty,ol.get("unit_cost"));jdbc.update("insert into stock_balances(location_id,product_id,quantity) values (?,?,?) on conflict(location_id,product_id) do update set quantity=stock_balances.quantity+excluded.quantity,version=stock_balances.version+1,updated_at=now()",location,product,qty);jdbc.update("insert into stock_movements(location_id,product_id,quantity_delta,movement_type,source_type,source_id,source_line_id,actor_id) values (?,?,?,'PURCHASE_RECEIPT','GOODS_RECEIPT',?,?,?)",location,product,qty,receipt,line.orderLineId(),actor);}Integer open=jdbc.queryForObject("select count(*) from purchase_order_lines where purchase_order_id=? and received_quantity<ordered_quantity",Integer.class,id);jdbc.update("update purchase_orders set status=? where id=?",open==0?"RECEIVED":"PARTIALLY_RECEIVED",id);audit.record(a.getName(),"GOODS_RECEIVED","GOODS_RECEIPT",receipt,null);return Map.of("id",receipt,"receiptNo",no,"status","CONFIRMED");}
}



